pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 amount, uint256 minSum) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        vm.assume(minSum <= amount);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint cEtherBefore = address(c).balance;
        bool reverted;
        try c.Collect(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint cEtherAfter = address(c).balance;
        assertTrue(!reverted &&
            balBefore == amount &&
            balAfter == 0 &&
            cEtherAfter == cEtherBefore - amount);
    }

    function testFuzz_run(uint256 amount, uint256 minSum) public {
        _run(amount, minSum);
    }

    receive() external payable {}
}
